// The AIA studio inside the browser (generated by tools/build-hubs.mjs).
// The prompts and the parsing below are copied unchanged from the server's lib/aiaStudio.js; only the storage differs:
// projects and reference images live in this browser (IndexedDB) instead of a server folder.

const MAX_IMAGES = 120;

/*__FROM_SERVER__*/

/*__MARKDOWN__*/

// ---------- storage: a tiny key-value store on IndexedDB ----------
let dbp = null;
function db() {
  if (!dbp) dbp = new Promise((ok, no) => {
    const r = indexedDB.open('hub-aia', 1);
    r.onupgradeneeded = () => r.result.createObjectStore('kv');
    r.onsuccess = () => ok(r.result);
    r.onerror = () => no(r.error);
  });
  return dbp;
}
async function tx(mode, fn) {
  const d = await db();
  return new Promise((ok, no) => {
    const t = d.transaction('kv', mode), s = t.objectStore('kv');
    let out;
    Promise.resolve(fn(s)).then((v) => { out = v; });
    t.oncomplete = () => ok(out); t.onerror = () => no(t.error); t.onabort = () => no(t.error);
  });
}
const req = (r) => new Promise((ok, no) => { r.onsuccess = () => ok(r.result); r.onerror = () => no(r.error); });
const kvGet = (k) => tx('readonly', (s) => req(s.get(k)));
const kvSet = (k, v) => tx('readwrite', (s) => req(s.put(v, k)));
const kvDel = (k) => tx('readwrite', (s) => req(s.delete(k)));
const kvKeys = (prefix) => tx('readonly', (s) => req(s.getAllKeys())).then((ks) => ks.filter((k) => String(k).startsWith(prefix)).sort());

const EXT = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp', 'image/gif': 'gif' };
async function decodeImg(dataUrl) {
  const m = /^data:([^;]+);base64,/.exec(dataUrl || '');
  if (!m) return null;
  const blob = await (await fetch(dataUrl)).blob();
  if (blob.size > 12 * 1024 * 1024) return null;
  return { ext: EXT[m[1]] || 'png', blob: blob.type ? blob : new Blob([blob], { type: m[1] }) };
}

async function stage({ stageId, dataUrl, note }) {
  if (!/^[a-z0-9-]{6,60}$/i.test(stageId || '')) throw new Error('stageId לא חוקי');
  const d = await decodeImg(dataUrl);
  if (!d) throw new Error('תמונה לא תקינה');
  const keys = await kvKeys('stage:' + stageId + ':');
  if (keys.length >= MAX_IMAGES) throw new Error(`מקסימום ${MAX_IMAGES} תמונות`);
  const name = `s${String(keys.length + 1).padStart(3, '0')}.${d.ext}`;
  await kvSet('stage:' + stageId + ':' + name, { blob: d.blob, note: note == null ? '' : String(note).slice(0, 400) });
  return { name };
}
async function clearStage(stageId) {
  for (const k of await kvKeys('stage:' + stageId + ':')) await kvDel(k);
}

async function create(brief, askAI) {
  const id = 'aia-' + Date.now().toString(36) + Math.random().toString(16).slice(2, 6);
  const assets = [];
  const add = async (blob, ext, note) => {
    const name = `ref-${assets.length + 1}.${ext}`;
    await kvSet('a:' + id + ':' + name, blob);
    assets.push({ name, url: `/api/aia/asset/${id}/${name}`, note: (note || '').slice(0, 400) });
  };
  if (brief.stageId && /^[a-z0-9-]{6,60}$/i.test(brief.stageId)) {
    const notes = Array.isArray(brief.stageNotes) ? brief.stageNotes : [];
    const keys = await kvKeys('stage:' + brief.stageId + ':');
    for (let i = 0; i < keys.length && assets.length < MAX_IMAGES; i++) {
      const rec = await kvGet(keys[i]);
      if (rec) await add(rec.blob, keys[i].split('.').pop(), notes[i] || rec.note);
    }
    await clearStage(brief.stageId);
  }
  for (const f of (Array.isArray(brief.files) ? brief.files : [])) {
    if (assets.length >= MAX_IMAGES) break;
    const d = await decodeImg(f.dataUrl);
    if (d) await add(d.blob, d.ext, f.note);
  }

  const c = await askAI(conceptPrompt(brief, assets));
  const concept = c.text.trim();
  const e = await askAI(expandPrompt(brief, assets, concept));
  const pkg = parsePackage(e.text, Number(brief.duration) || 8);
  pkg.concept = concept;
  let title = brief.title || '';
  try { const t = await askAI(titlePrompt(concept)); title = cleanTitle(t.text) || title; } catch (x) { /* the title of the brief stays */ }
  pkg.title = title || pkg.title;

  const project = {
    id, createdAt: new Date().toISOString(),
    brief: { type: brief.type, title: brief.title, style: brief.style, mood: brief.mood, aspect: brief.aspect, duration: brief.duration, text: brief.text || '' },
    assets, package: pkg, aiSource: c.source
  };
  await kvSet('p:' + id, project);
  const idx = ((await kvGet('index')) || []);
  idx.unshift({ id, title: pkg.title || brief.title || 'ללא כותרת', type: brief.type, createdAt: project.createdAt, assetCount: assets.length });
  await kvSet('index', idx.slice(0, 200));
  return project;
}

async function list() {
  return { projects: (await kvGet('index')) || [], maxImages: MAX_IMAGES, canRender: false, beds: [], transitions: [] };
}
const get = (id) => kvGet('p:' + id);
async function remove(id) {
  await kvSet('index', ((await kvGet('index')) || []).filter((p) => p.id !== id));
  await kvDel('p:' + id);
  for (const k of await kvKeys('a:' + id + ':')) await kvDel(k);
}
const asset = (id, name) => kvGet('a:' + id + ':' + name);
async function markdown(id) { const p = await get(id); return p ? toMarkdown(p) : null; }

module.exports = { list, stage, clearStage, create, get, remove, asset, markdown };
